import Foundation
import Security

// Vertical-slice tests for the imported-identity bootstrap path. Fixtures are
// synthetic PKCS#12 identities generated by the wrapper script (argv[1] = dir).
// Nothing here is a real Apple identity; no private key or password is logged.

var failures = 0
func check(_ cond: Bool, _ name: String) {
	if cond { print("PASS: \(name)") } else { failures += 1; print("FAIL: \(name)") }
}

let dir = CommandLine.arguments.count > 1 ? CommandLine.arguments[1] : "."
func data(_ f: String) -> Data { (try? Data(contentsOf: URL(fileURLWithPath: "\(dir)/\(f)"))) ?? Data() }

let team = "V54K5JYGS4"
let now = Date()
let farFuture = Date(timeIntervalSinceNow: 10 * 365 * 86_400)

// Import: correct vs wrong password.
let imported = ZagImportedSigningIdentity.importIdentity(pkcs12: data("id.p12"), password: "correct-horse")
check({ if case .success = imported { return true }; return false }(), "import synthetic PKCS#12 with correct password")
check({ if case .failure(.wrongPasswordOrCorrupt) = ZagImportedSigningIdentity.importIdentity(pkcs12: data("id.p12"), password: "nope") { return true }; return false }(),
	  "wrong password -> wrongPasswordOrCorrupt")
check({ if case .failure(.wrongPasswordOrCorrupt) = ZagImportedSigningIdentity.importIdentity(pkcs12: Data([0,1,2,3]), password: "x") { return true }; return false }(),
	  "corrupt data -> wrongPasswordOrCorrupt")

guard case .success(let id) = imported else {
	print("FAILURES: \(failures + 1)  (could not import primary fixture)")
	exit(1)
}

// Validation: correspondence + development suitability + team + validity window.
switch ZagImportedSigningIdentity.validate(id, now: now, expectedTeam: team) {
case .success(let info):
	check(info.team == team, "validate: team (OU) is the expected team")
	check(info.isDevelopment, "validate: recognised as a development certificate")
	check(info.isNonExtractable == false, "imported identity is NOT marked non-extractable")
	check(info.notAfter > now, "validate: certificate is within its validity window")
	check(!info.serialNumber.isEmpty, "validate: serial parsed")
case .failure(let e):
	check(false, "validate should succeed on the primary fixture (got \(e))")
}

// Expired: evaluated at a time past notAfter.
check({ if case .failure(.certExpired) = ZagImportedSigningIdentity.validate(id, now: farFuture, expectedTeam: team) { return true }; return false }(),
	  "expired certificate -> certExpired")
// Team mismatch.
check({ if case .failure(.teamMismatch) = ZagImportedSigningIdentity.validate(id, now: now, expectedTeam: "WRONGTEAM0") { return true }; return false }(),
	  "wrong expected team -> teamMismatch")

// Non-development certificate rejected.
if case .success(let server) = ZagImportedSigningIdentity.importIdentity(pkcs12: data("server.p12"), password: "pw3") {
	check({ if case .failure(.notDevelopmentCertificate) = ZagImportedSigningIdentity.validate(server, now: now) { return true }; return false }(),
		  "non-development certificate -> notDevelopmentCertificate")
} else { check(false, "import server.p12 fixture") }

// Correspondence: a different identity's certificate must not verify this key.
if case .success(let other) = ZagImportedSigningIdentity.importIdentity(pkcs12: data("id2.p12"), password: "pw2") {
	var c1: SecCertificate?; SecIdentityCopyCertificate(id, &c1)
	var k1: SecKey?; SecIdentityCopyPrivateKey(id, &k1)
	var c2: SecCertificate?; SecIdentityCopyCertificate(other, &c2)
	check(ZagImportedSigningIdentity.corresponds(key: k1!, certificate: c1!), "corresponds: key matches its own certificate")
	check(!ZagImportedSigningIdentity.corresponds(key: k1!, certificate: c2!), "corresponds: key does NOT match a different certificate")
	// Team mismatch is enforced against id2's different team as well.
	check({ if case .failure(.teamMismatch) = ZagImportedSigningIdentity.validate(other, now: now, expectedTeam: team) { return true }; return false }(),
		  "second identity's different team -> teamMismatch against expected team")
	// A signature from id must not verify under id2.
	let payload = Data("zag-test-payload".utf8)
	if let sig = ZagImportedSigningIdentity.sign(payload, identity: id) {
		check(!ZagImportedSigningIdentity.verify(sig, payload: payload, identity: other), "signature from one identity does not verify under another")
	}
} else { check(false, "import id2.p12 fixture") }

// Sign / verify round-trip with the imported key.
let payload = Data("the quick brown fox".utf8)
if let sig = ZagImportedSigningIdentity.sign(payload, identity: id) {
	check(ZagImportedSigningIdentity.verify(sig, payload: payload, identity: id), "sign then verify round-trip succeeds")
	check(!ZagImportedSigningIdentity.verify(sig, payload: Data("tampered".utf8), identity: id), "verify rejects a tampered payload")
} else { check(false, "sign a payload with the imported key") }

// Zsign callback: the SAME raw PKCS#1 v1.5 DigestInfo signer the device path uses.
// A SHA-256 DigestInfo is 19 header bytes + 32 hash bytes = 51 bytes; RSA-2048
// produces a 256-byte signature.
if let signer = ZagImportedSigningIdentity.zsignSigner(id) {
	let sha256DigestInfoPrefix = Data([0x30,0x31,0x30,0x0d,0x06,0x09,0x60,0x86,0x48,0x01,0x65,0x03,0x04,0x02,0x01,0x05,0x00,0x04,0x20])
	let digestInfo = sha256DigestInfoPrefix + Data(repeating: 0xAB, count: 32)
	let sig = signer(digestInfo)
	check(sig != nil, "zsign callback produces a signature")
	check(sig?.count == 256, "zsign signature is RSA-2048 sized (256 bytes)")
} else { check(false, "obtain zsign signer from imported identity") }

// MARK: Phase 2/3 — profile parsing + authoritative identity/profile/device/bundle match.
var idCert: SecCertificate?; SecIdentityCopyCertificate(id, &idCert)
let idDER = SecCertificateCopyData(idCert!) as Data
let udid = "00009999-000ABCDEF1234567"   // synthetic provisioning UDID (NOT a CoreDevice id)
let bundle = "com.zagstore.test"

guard let profile = ZagMobileProvision.parseUnverified(data("profile.plist")) else {
	print("FAIL: parse synthetic profile fixture"); print("FAILURES: \(failures + 1)"); exit(1)
}
check(profile.teamIdentifier == team, "profile parse: TeamIdentifier")
check(profile.developerCertificates.count == 1, "profile parse: DeveloperCertificates present")
check(profile.provisionedDevices.contains(udid), "profile parse: ProvisionedDevices")
check(profile.entitlements["application-identifier"] != nil, "profile parse: entitlement values")
check(profile.entitlements["get-task-allow"] == .bool(true), "profile parse: boolean entitlement value")
check(profile.entitlements["keychain-access-groups"] == .array([.string("V54K5JYGS4.*")]), "profile parse: array entitlement value")

let reqOK: [String: ZagEntitlementValue] = [
	"application-identifier": .string("V54K5JYGS4.com.zagstore.test"),
	"get-task-allow": .bool(true),
	"keychain-access-groups": .array([.string("V54K5JYGS4.myapp")]),   // covered by granted V54K5JYGS4.*
]
func ev(idDER d: Data = idDER, team t: String? = team, dev: Bool = true, p: ZagProfileContents = profile,
		device: String = udid, bundleID: String = bundle, ent: [String: ZagEntitlementValue] = reqOK,
		cms: Bool = true, now n: Date = now) -> ZagProfileMatchResult {
	ZagImportedIdentityProfileMatch.evaluate(identityCertificateDER: d, identityTeam: t, identityIsDevelopment: dev,
		profile: p, deviceProvisioningUDID: device, targetBundleID: bundleID, requestedEntitlements: ent, cmsVerified: cms, now: n)
}
check(ev() == .compatible, "match: fully compatible (cert/team/device/bundle/entitlement VALUES)")
check(ev(cms: false) == .profileNotCMSVerified, "match: unverified CMS fails closed for real signing")
check(ev(dev: false) == .notDevelopmentCertificate, "match: non-development certificate fails closed")
// A different identity's certificate is not in the profile.
if case .success(let other) = ZagImportedSigningIdentity.importIdentity(pkcs12: data("id2.p12"), password: "pw2") {
	var oc: SecCertificate?; SecIdentityCopyCertificate(other, &oc)
	check(ev(idDER: SecCertificateCopyData(oc!) as Data) == .certificateNotInProfile, "match: certificate not in profile (DER/SHA-256 compare)")
}
check(ev(team: "WRONGTEAM0") == .teamMismatch, "match: team mismatch")
check(ev(device: "00000000-000000000000000") == .deviceNotProvisioned, "match: device not provisioned")
let afterProfile = Date(timeIntervalSince1970: 5_000_000_000)   // ~2128, past the fixture's 2099 expiry
check(ev(now: afterProfile) == .profileExpired, "match: expired profile")
check(ev(bundleID: "com.zagstore.other") == .bundleMismatch, "match: wrong bundle id")
// Entitlement VALUE/structure checks (not just keys).
check(ev(ent: ["com.apple.developer.icloud-services": .bool(true)]) == .disallowedEntitlements(["com.apple.developer.icloud-services"]),
	  "entitlement: key the profile does not grant -> rejected")
check(ev(ent: ["get-task-allow": .bool(false)]) == .disallowedEntitlements(["get-task-allow"]),
	  "entitlement: boolean value mismatch -> rejected")
check(ev(ent: ["keychain-access-groups": .array([.string("OTHERTEAM.foo")])]) == .disallowedEntitlements(["keychain-access-groups"]),
	  "entitlement: keychain group outside the granted wildcard -> rejected")
check(ev(ent: ["keychain-access-groups": .array([.string("V54K5JYGS4.anything")])]) == .compatible,
	  "entitlement: keychain group under the granted wildcard -> allowed")
check(ev(ent: ["application-identifier": .string("V54K5JYGS4.wrong.bundle")]) == .disallowedEntitlements(["application-identifier"]),
	  "entitlement: application-identifier value mismatch -> rejected")
check(ev(ent: ["get-task-allow": .string("true")]) == .disallowedEntitlements(["get-task-allow"]),
	  "entitlement: type mismatch (string vs bool) -> rejected")

// ZagEntitlementAudit unit rules.
check(ZagEntitlementAudit.stringGrants(granted: "V54K5JYGS4.*", requested: "V54K5JYGS4.app"), "stringGrants: trailing * prefix wildcard")
check(!ZagEntitlementAudit.stringGrants(granted: "V54K5JYGS4.*", requested: "OTHER.app"), "stringGrants: wrong prefix rejected")
check(ZagEntitlementAudit.stringGrants(granted: "*", requested: "anything"), "stringGrants: bare * grants anything")
check(ZagEntitlementAudit.stringGrants(granted: "exact", requested: "exact"), "stringGrants: exact match")
check(!ZagEntitlementAudit.stringGrants(granted: "exact", requested: "exacto"), "stringGrants: non-match rejected")
check(ZagEntitlementAudit.grants(.array([.string("A.*")]), .array([.string("A.x"), .string("A.y")]), key: "k"),
	  "grants: array all elements covered by a granted wildcard")
check(!ZagEntitlementAudit.grants(.array([.string("A.*")]), .array([.string("A.x"), .string("B.y")]), key: "k"),
	  "grants: array with an uncovered element rejected")
check(!ZagEntitlementAudit.grants(.other, .bool(true), key: "k"), "grants: unsupported/other value fails closed")

// Wildcard bundle semantics (unit).
check(ZagImportedIdentityProfileMatch.bundleMatches(target: "com.a.b", applicationIdentifier: "TEAMID.*", team: "TEAMID"), "wildcard: bare * matches")
check(ZagImportedIdentityProfileMatch.bundleMatches(target: "com.foo.bar", applicationIdentifier: "TEAMID.com.foo.*", team: "TEAMID"), "wildcard: prefix .* matches child")
check(!ZagImportedIdentityProfileMatch.bundleMatches(target: "com.other", applicationIdentifier: "TEAMID.com.foo.*", team: "TEAMID"), "wildcard: prefix .* rejects non-child")
check(!ZagImportedIdentityProfileMatch.bundleMatches(target: "com.foo.bar", applicationIdentifier: "OTHER.com.foo.bar", team: "TEAMID"), "wildcard: wrong team prefix rejected")

// Explicit signing-source selection (no silent fallback).
check(ZagSigningSource.deviceGenerated(keySlot: "s1").usesNonExtractableKey, "source: device-generated uses non-extractable key")
check(ZagSigningSource.imported(label: "x").isImported && !ZagSigningSource.imported(label: "x").usesNonExtractableKey, "source: imported is distinct, not non-extractable")
check(ZagSigningSource.imported(label: "a") != ZagSigningSource.imported(label: "b"), "source: labels distinguish imported identities")

// End-to-end: a signature by the imported key verifies under the EXACT certificate
// the profile authorizes (the signing step the on-device Zsign callback performs).
let cdPayload = Data("synthetic CodeDirectory for an IPA".utf8)
if let sig = ZagImportedSigningIdentity.sign(cdPayload, identity: id),
   let profileCert = SecCertificateCreateWithData(nil, profile.developerCertificates[0] as CFData),
   let profileCertKey = SecCertificateCopyKey(profileCert) {
	check(SecKeyVerifySignature(profileCertKey, .rsaSignatureMessagePKCS1v15SHA256, cdPayload as CFData, sig as CFData, nil),
		  "end-to-end: imported-key signature verifies under the profile's embedded certificate")
} else { check(false, "end-to-end: sign + load profile certificate") }

// End-to-end PREFLIGHT: cryptographic CMS verification composed with the full
// compatibility match. CMS trust is derived ONLY from ZagCMSVerifier — there is
// no caller boolean/Mac flag shortcut.
let synRoot = ((try? String(contentsOf: URL(fileURLWithPath: "\(dir)/synthetic_root_sha256.txt"), encoding: .utf8)) ?? "")
	.trimmingCharacters(in: .whitespacesAndNewlines)
let reqEnt: [String: ZagEntitlementValue] = ["application-identifier": .string("V54K5JYGS4.com.zagstore.test"), "get-task-allow": .bool(true)]
func preflight(_ file: String, device: String = udid, roots: Set<String>) -> ZagSigningPreflightResult {
	ZagSigningPreflight.prepare(profileData: data(file), identityCertificateDER: idDER, identityTeam: team,
		identityIsDevelopment: true, deviceProvisioningUDID: device, targetBundleID: bundle,
		requestedEntitlements: reqEnt, trustedRootSHA256: roots, now: Date())
}
if case .ready = preflight("profile_signed.der", roots: [synRoot]) {
	check(true, "preflight: cryptographically verified CMS + compatible identity -> ready")
} else { check(false, "preflight: verified CMS should be ready") }
check(preflight("profile_untrusted.der", roots: [synRoot]) == .profileNotTrusted,
	  "preflight: untrusted CMS chain -> profileNotTrusted (identical contents, no shortcut)")
check(preflight("profile_signed.der", roots: ["ff" + String(synRoot.dropFirst(2))]) == .profileNotTrusted,
	  "preflight: wrong pinned anchor -> profileNotTrusted")
if case .incompatible(.deviceNotProvisioned) = preflight("profile_signed.der", device: "00000000-000000000000000", roots: [synRoot]) {
	check(true, "preflight: verified CMS but wrong device -> incompatible, not ready")
} else { check(false, "preflight: wrong device should be incompatible") }

print(failures == 0 ? "ALL PASS" : "FAILURES: \(failures)")
exit(failures == 0 ? 0 : 1)
